jest.mock('./logger');

import { UserService } from './userService';
import { logger } from './logger';

describe('UserService', () => {
  let userService: UserService;

  beforeEach(() => {
    userService = new UserService();
    jest.clearAllMocks();
  });

  test('should log info when creating user', () => {
    userService.createUser('Alice');

    expect(logger.info).toHaveBeenCalledWith('Creating user: Alice');
    expect(logger.info).toHaveBeenCalledTimes(1);
  });

  test('should log info when deleting user', () => {
    userService.deleteUser('123');

    expect(logger.info).toHaveBeenCalledWith('Deleting user: 123');
    expect(logger.info).toHaveBeenCalledTimes(1);
  });

  test('should log correct message for multiple operations', () => {
    userService.createUser('Bob');
    userService.deleteUser('456');

    expect(logger.info).toHaveBeenCalledTimes(2);
    expect(logger.info).toHaveBeenNthCalledWith(1, 'Creating user: Bob');
    expect(logger.info).toHaveBeenNthCalledWith(2, 'Deleting user: 456');
  });
});

