// Jest tests
describe('ShoppingCart', () => {
  let cart: ShoppingCart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  test('should calculate total after adding an item', () => {
    cart.addItem('Book', 10, 2);

    expect(cart.getTotal()).toBe(20);
  });

  test('should accumulate quantity when the same item is added twice', () => {
    cart.addItem('Book', 10, 1);
    cart.addItem('Book', 10, 1);

    expect(cart.getItemCount()).toBe(1);
    expect(cart.getTotal()).toBe(20);
  });

  test('should decrease total after partially removing an item', () => {
    cart.addItem('Book', 10, 2);
    cart.removeItem('Book', 1);

    expect(cart.getTotal()).toBe(10);
  });

  test('should remove the item entirely once quantity reaches zero', () => {
    cart.addItem('Book', 10, 1);
    cart.removeItem('Book', 1);

    expect(cart.getItemCount()).toBe(0);
    expect(cart.getTotal()).toBe(0);
  });

  test('should not throw and not change total when removing an unknown item', () => {
    cart.addItem('Book', 10, 1);

    expect(() => cart.removeItem('Pen')).not.toThrow();
    expect(cart.getTotal()).toBe(10);
  });

  test('should not go negative when removing more than is in the cart', () => {
    cart.addItem('Book', 10, 1);
    cart.removeItem('Book', 5);

    expect(cart.getItemCount()).toBe(0);
    expect(cart.getTotal()).toBe(0);
  });
});

description.en:
You have a `UserProfile` component that fetches a user by id on mount. It shows a loading spinner while the request is in flight, then renders the user's name and email once loaded. If the fetch fails, it shows an error message. It also lets the user edit and save their name through a small inline form.

**Requirements:**

- Use React Testing Library together with `userEvent` (not `fireEvent`) for all interactions
- Mock the `fetchUser` and `updateUser` API functions (do not hit a real network)
- Cover: initial loading state, successful render, fetch failure, and a successful edit-and-save flow
- Use `waitFor` (or `findBy*` queries) for anything that resolves asynchronously
- Query by role/text, not by test id or class name

**Component signature:**

```typescript
interface User {
  id: string;
  name: string;
  email: string;
}

declare function fetchUser(id: string): Promise<User>;
declare function updateUser(id: string, patch: Partial<User>): Promise<User>;

interface UserProfileProps {
  userId: string;
}

declare function UserProfile(props: UserProfileProps): JSX.Element;
```

**Example behavior:**

- On mount: shows text `Loading...`
- After `fetchUser` resolves: shows the user's name and email, plus an "Edit" button
- After `fetchUser` rejects: shows `Failed to load user`
- Clicking "Edit" reveals a text input pre-filled with the current name and a "Save" button
- Typing a new name and clicking "Save" calls `updateUser` and, on success, re-renders the new name

**Edge cases:**

- `fetchUser` rejects (network/error state)
- `updateUser` rejects (should show an inline error and keep the form open, not crash)
- Component unmounts while a request is still pending (no "state update on unmounted component" warning)

