import { renderHook, act } from '@testing-library/react';
import { useUserForm } from './useUserForm';

const initialValues = { name: '', email: '' };

function noErrors() {
  return {};
}

function requireName(values: { name: string; email: string }) {
  return values.name.trim() ? {} : { name: 'Name is required' };
}

describe('useUserForm', () => {
  test('setField updates values and marks the form dirty', () => {
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: noErrors, onSubmit: jest.fn() })
    );

    act(() => {
      result.current.setField('name', 'Ada');
    });

    expect(result.current.values.name).toBe('Ada');
    expect(result.current.isDirty).toBe(true);
  });

  test('validate is re-run on every field change and populates errors', () => {
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: requireName, onSubmit: jest.fn() })
    );

    act(() => {
      result.current.setField('name', '');
    });
    expect(result.current.errors.name).toBe('Name is required');

    act(() => {
      result.current.setField('name', 'Grace');
    });
    expect(result.current.errors.name).toBeUndefined();
  });

  test('reset restores initialValues, clears errors and isDirty', () => {
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: requireName, onSubmit: jest.fn() })
    );

    act(() => {
      result.current.setField('name', 'Grace');
    });
    act(() => {
      result.current.reset();
    });

    expect(result.current.values).toEqual(initialValues);
    expect(result.current.errors).toEqual({});
    expect(result.current.isDirty).toBe(false);
  });

  test('submit calls onSubmit only when there are no errors, and toggles isSubmitting', async () => {
    const onSubmit = jest.fn().mockResolvedValue(undefined);
    const { result } = renderHook(() =>
      useUserForm({ initialValues, validate: requireName, onSubmit })
    );

    await act(async () => {
      await result.current.submit();
    });
    expect(onSubmit).not.toHaveBeenCalled();

    act(() => {
      result.current.setField('name', 'Grace');
    });

    await act(async () => {
      await result.current.submit();
    });
    expect(onSubmit).toHaveBeenCalledWith({ name: 'Grace', email: '' });
    expect(result.current.isSubmitting).toBe(false);
  });

  test('submit resets isSubmitting to false even when onSubmit rejects', async () => {
    const onSubmit = jest.fn().mockRejectedValue(new Error('server error'));
    const { result } = renderHook(() =>
      useUserForm({ initialValues: { name: 'Grace', email: '' }, validate: noErrors, onSubmit })
    );

    await act(async () => {
      await result.current.submit().catch(() => {});
    });

    expect(result.current.isSubmitting).toBe(false);
  });
});

description.en:
You have a `CheckoutForm` component wrapped by an `ErrorBoundary`. On submit it calls a `placeOrder` API function. Write an integration test that exercises the whole flow. It covers a successful submission, a recoverable API failure with a retry button, and an unexpected render-time error. That last error must be caught by the boundary instead of crashing the test.

**Requirements:**

- Render `CheckoutForm` wrapped in `ErrorBoundary` together, as it's actually used in the app
- Mock `placeOrder` to control success, recoverable failure, and a thrown render error
- Use `userEvent` for form filling and button clicks
- Verify the error boundary's fallback interface appears only for the render-crash case, not for the API failure case
- Suppress the expected `console.error` output from React's error boundary logging so test output stays readable, and restore it afterward

**Components involved:**

```typescript
declare function placeOrder(
  order: { item: string; quantity: number }
): Promise<{ orderId: string }>;

interface ErrorBoundaryProps {
  children: React.ReactNode;
}
declare class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  { hasError: boolean }
> {}

declare function CheckoutForm(): JSX.Element;
```

**Example behavior:**

- Fill "item" and "quantity", click "Place order" → on success, shows `Order #<id> placed`
- On a recoverable `placeOrder` rejection, shows `Order failed. ` plus a "Retry" button; clicking retry re-submits
- If rendering the confirmation view itself throws (simulated via a malformed order id), the `ErrorBoundary` renders `Something went wrong` instead of the confirmation. The rest of the page doesn't crash

**Edge cases:**

- Clicking "Place order" with an empty "item" field should show a validation message and never call `placeOrder`
- Retrying after failure must call `placeOrder` again with the same submitted values, not the empty initial ones
- `console.error` calls triggered by the intentional render-crash test must not leak into other tests' output

