import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ErrorBoundary } from './ErrorBoundary';
import { CheckoutForm } from './CheckoutForm';
import { placeOrder } from './api';

jest.mock('./api');
const mockedPlaceOrder = placeOrder as jest.MockedFunction<typeof placeOrder>;

function renderCheckout() {
  return render(
    <ErrorBoundary>
      <CheckoutForm />
    </ErrorBoundary>
  );
}

async function fillAndSubmit(user: ReturnType<typeof userEvent.setup>, item = 'Keyboard', quantity = '2') {
  if (item) {
    await user.type(screen.getByRole('textbox', { name: /item/i }), item);
  }
  await user.clear(screen.getByRole('spinbutton', { name: /quantity/i }));
  await user.type(screen.getByRole('spinbutton', { name: /quantity/i }), quantity);
  await user.click(screen.getByRole('button', { name: /place order/i }));
}

describe('CheckoutForm integration', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('shows validation and never calls placeOrder when item is empty', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await fillAndSubmit(user, '');

    expect(await screen.findByText(/item is required/i)).toBeInTheDocument();
    expect(mockedPlaceOrder).not.toHaveBeenCalled();
  });

  test('successful submission shows the order confirmation', async () => {
    mockedPlaceOrder.mockResolvedValue({ orderId: 'A100' });
    const user = userEvent.setup();
    renderCheckout();

    await fillAndSubmit(user);

    expect(await screen.findByText('Order #A100 placed')).toBeInTheDocument();
  });

  test('recoverable failure shows Retry, and retry resubmits the same values', async () => {
    mockedPlaceOrder
      .mockRejectedValueOnce(new Error('timeout'))
      .mockResolvedValueOnce({ orderId: 'B200' });
    const user = userEvent.setup();
    renderCheckout();

    await fillAndSubmit(user, 'Mouse', '3');

    expect(await screen.findByText(/order failed/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /retry/i }));

    await waitFor(() => {
      expect(mockedPlaceOrder).toHaveBeenLastCalledWith({ item: 'Mouse', quantity: 3 });
    });
    expect(await screen.findByText('Order #B200 placed')).toBeInTheDocument();
  });

  test('a render-time crash in the confirmation view is caught by the ErrorBoundary', async () => {
    const consoleSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    // 'CRASH' is a sentinel item name the confirmation view throws on when rendering,
    // simulating an unexpected render-time bug rather than an API failure.
    mockedPlaceOrder.mockResolvedValue({ orderId: 'CRASH' });
    const user = userEvent.setup();
    renderCheckout();

    await fillAndSubmit(user);

    expect(await screen.findByText('Something went wrong')).toBeInTheDocument();
    expect(screen.queryByText(/order #.* placed/i)).not.toBeInTheDocument();

    consoleSpy.mockRestore();
  });
});

