interface NotificationEvent {
  type: 'notification';
  payload: { id: string; message: string };
}

class FakeWebSocket {
  onopen: (() => void) | null = null;
  onmessage: ((event: { data: string }) => void) | null = null;
  onclose: (() => void) | null = null;
  onerror: ((err: unknown) => void) | null = null;

  send(_data: string) {}
  close() {
    this.onclose?.();
  }

  simulateMessage(data: unknown) {
    this.onmessage?.({ data: JSON.stringify(data) });
  }
  simulateRawMessage(rawString: string) {
    this.onmessage?.({ data: rawString });
  }
  simulateClose() {
    this.onclose?.();
  }
}

class NotificationClient {
  private socket: FakeWebSocket | null = null;
  private subscribers = new Set<(event: NotificationEvent) => void>();
  private reconnectAttempts = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private manuallyDisconnected = false;

  constructor(private url: string, private wsFactory: (url: string) => FakeWebSocket) {}

  connect() {
    this.manuallyDisconnected = false;
    const socket = this.wsFactory(this.url);
    this.socket = socket;

    socket.onopen = () => {
      this.reconnectAttempts = 0;
    };

    socket.onmessage = (event) => {
      let parsed: unknown;
      try {
        parsed = JSON.parse(event.data);
      } catch {
        return; // malformed JSON: silently ignore, don't crash
      }

      if (
        parsed &&
        typeof parsed === 'object' &&
        (parsed as { type?: string }).type === 'notification'
      ) {
        const notif = parsed as NotificationEvent;
        for (const cb of this.subscribers) {
          cb(notif);
        }
      }
      // heartbeat and unknown types: no-op
    };

    socket.onclose = () => {
      if (this.manuallyDisconnected) return;
      if (this.reconnectTimer !== null) return; // already scheduled, don't stack timers

      const delay = Math.min(1000 * 2 ** this.reconnectAttempts, 30000);
      this.reconnectAttempts += 1;
      this.reconnectTimer = setTimeout(() => {
        this.reconnectTimer = null;
        this.connect();
      }, delay);
    };
  }

  disconnect() {
    this.manuallyDisconnected = true;
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.socket?.close();
  }

  onNotification(callback: (event: NotificationEvent) => void): () => void {
    this.subscribers.add(callback);
    let unsubscribed = false;
    return () => {
      if (unsubscribed) return;
      unsubscribed = true;
      this.subscribers.delete(callback);
    };
  }
}

describe('NotificationClient', () => {
  let fakeSockets: FakeWebSocket[];
  let wsFactory: (url: string) => FakeWebSocket;

  beforeEach(() => {
    fakeSockets = [];
    wsFactory = () => {
      const socket = new FakeWebSocket();
      fakeSockets.push(socket);
      return socket;
    };
  });

  test('fires callback only for notification type, not heartbeat', () => {
    const client = new NotificationClient('ws://test', wsFactory);
    client.connect();
    const received: NotificationEvent[] = [];
    client.onNotification((e) => received.push(e));

    fakeSockets[0].simulateMessage({ type: 'heartbeat' });
    fakeSockets[0].simulateMessage({ type: 'notification', payload: { id: '1', message: 'hi' } });

    expect(received).toHaveLength(1);
    expect(received[0].payload.id).toBe('1');
  });

  test('multiple subscribers all fire, unsubscribe stops further calls', () => {
    const client = new NotificationClient('ws://test', wsFactory);
    client.connect();
    const calls1: NotificationEvent[] = [];
    const calls2: NotificationEvent[] = [];
    client.onNotification((e) => calls1.push(e));
    const unsubscribe2 = client.onNotification((e) => calls2.push(e));

    fakeSockets[0].simulateMessage({ type: 'notification', payload: { id: '1', message: 'a' } });
    unsubscribe2();
    fakeSockets[0].simulateMessage({ type: 'notification', payload: { id: '2', message: 'b' } });

    expect(calls1).toHaveLength(2);
    expect(calls2).toHaveLength(1);
  });

  test('reconnects with exponential backoff after disconnect', () => {
    jest.useFakeTimers();
    const client = new NotificationClient('ws://test', wsFactory);
    client.connect();

    fakeSockets[0].simulateClose();
    expect(fakeSockets).toHaveLength(1);
    jest.advanceTimersByTime(1000);
    expect(fakeSockets).toHaveLength(2);

    fakeSockets[1].simulateClose();
    jest.advanceTimersByTime(1999);
    expect(fakeSockets).toHaveLength(2);
    jest.advanceTimersByTime(1);
    expect(fakeSockets).toHaveLength(3);

    jest.useRealTimers();
  });

  test('malformed JSON does not crash client or fire callbacks', () => {
    const client = new NotificationClient('ws://test', wsFactory);
    client.connect();
    const received: NotificationEvent[] = [];
    client.onNotification((e) => received.push(e));

    expect(() => fakeSockets[0].simulateRawMessage('{not valid json')).not.toThrow();
    expect(received).toHaveLength(0);
  });
});

