class RequestCache {
  private cache: Record<string, number> = {};
  private requestCount = 0;

  fetchWithCache(key: string, computeFn: () => number): number {
    this.requestCount += 1;
    if (key in this.cache) return this.cache[key];
    const value = computeFn();
    this.cache[key] = value;
    return value;
  }

  getRequestCount(): number {
    return this.requestCount;
  }

  reset(): void {
    this.cache = {};
    this.requestCount = 0;
  }
}

// Module-level singleton for production use (unchanged public behavior)
const productionCache = new RequestCache();
function fetchWithCache(key: string, computeFn: () => number): number {
  return productionCache.fetchWithCache(key, computeFn);
}
function getRequestCount(): number {
  return productionCache.getRequestCount();
}

// --- Diagnostic tool ---
interface TestRunResult {
  order: string[];
  outcomes: Record<string, 'pass' | 'fail'>;
}

function detectSharedState(runs: TestRunResult[]): string[] {
  const outcomesByTest: Record<string, Set<'pass' | 'fail'>> = {};

  for (const run of runs) {
    for (const testName of Object.keys(run.outcomes)) {
      if (!outcomesByTest[testName]) {
        outcomesByTest[testName] = new Set();
      }
      outcomesByTest[testName].add(run.outcomes[testName]);
    }
  }

  const orderDependent: string[] = [];
  for (const [testName, outcomeSet] of Object.entries(outcomesByTest)) {
    if (outcomeSet.size > 1) {
      orderDependent.push(testName);
    }
  }

  return orderDependent;
}

// --- Corrected, isolated test file ---
describe('RequestCache (isolated)', () => {
  let cacheInstance: RequestCache;

  beforeEach(() => {
    cacheInstance = new RequestCache(); // fresh instance every test, no shared module state
  });

  test('caches a computed value', () => {
    const result = cacheInstance.fetchWithCache('a', () => 42);
    expect(result).toBe(42);
    expect(cacheInstance.getRequestCount()).toBe(1);
  });

  test('returns cached value on second call, does not recompute', () => {
    cacheInstance.fetchWithCache('a', () => 42);
    const result = cacheInstance.fetchWithCache('a', () => 999);
    expect(result).toBe(42); // still the first computed value
    expect(cacheInstance.getRequestCount()).toBe(2); // both calls counted, only one compute
  });

  test('different keys are cached independently', () => {
    cacheInstance.fetchWithCache('a', () => 1);
    cacheInstance.fetchWithCache('b', () => 2);
    expect(cacheInstance.fetchWithCache('a', () => 999)).toBe(1);
    expect(cacheInstance.fetchWithCache('b', () => 999)).toBe(2);
  });
});

// --- Order-independence demonstration ---
function runSuiteInOrder(order: ('caches' | 'cached' | 'independent')[]): Record<string, 'pass' | 'fail'> {
  const outcomes: Record<string, 'pass' | 'fail'> = {};
  let instance: RequestCache;

  const setup = () => {
    instance = new RequestCache();
  };

  const runners: Record<string, () => void> = {
    caches: () => {
      setup();
      const result = instance.fetchWithCache('a', () => 42);
      if (result !== 42 || instance.getRequestCount() !== 1) throw new Error('fail');
    },
    cached: () => {
      setup();
      instance.fetchWithCache('a', () => 42);
      const result = instance.fetchWithCache('a', () => 999);
      if (result !== 42) throw new Error('fail');
    },
    independent: () => {
      setup();
      instance.fetchWithCache('a', () => 1);
      instance.fetchWithCache('b', () => 2);
      if (instance.fetchWithCache('a', () => 999) !== 1) throw new Error('fail');
    },
  };

  for (const testName of order) {
    try {
      runners[testName]();
      outcomes[testName] = 'pass';
    } catch {
      outcomes[testName] = 'fail';
    }
  }
  return outcomes;
}

describe('order independence proof', () => {
  test('identical results across 3 different execution orders', () => {
    const orderA: ('caches' | 'cached' | 'independent')[] = ['caches', 'cached', 'independent'];
    const orderB: ('caches' | 'cached' | 'independent')[] = ['independent', 'caches', 'cached'];
    const orderC: ('caches' | 'cached' | 'independent')[] = ['cached', 'independent', 'caches'];

    const resultA = runSuiteInOrder(orderA);
    const resultB = runSuiteInOrder(orderB);
    const resultC = runSuiteInOrder(orderC);

    expect(resultA).toEqual({ caches: 'pass', cached: 'pass', independent: 'pass' });
    expect(resultB).toEqual({ caches: 'pass', cached: 'pass', independent: 'pass' });
    expect(resultC).toEqual({ caches: 'pass', cached: 'pass', independent: 'pass' });

    const runs: TestRunResult[] = [
      { order: orderA, outcomes: resultA },
      { order: orderB, outcomes: resultB },
      { order: orderC, outcomes: resultC },
    ];
    expect(detectSharedState(runs)).toEqual([]);
  });
});

description.en:
Your team has 100% line coverage on a `discountCalculator` module, yet a production bug still shipped: a wrong comparison operator. The existing tests never exercised the boundary that would have caught it.

Build a minimal mutation testing engine. It takes a function's source as a string and applies small semantic mutations, such as flipping `>` to `>=` or `&&` to `||`.

It re-runs the given test suite against each mutant and reports which mutations survived, meaning the tests still passed while the code was wrong. A surviving mutant marks a coverage gap that line and branch coverage cannot reveal on their own.

**Requirements:**

- Implement mutators for at least three groups. Comparison flips: `>` ↔ `>=`, `<` ↔ `<=`, `===` ↔ `!==`. Boolean logic flips: `&&` ↔ `||`. Arithmetic flips: `+` ↔ `-`
- For a given source string, generate all single-mutation variants (one mutation applied per variant — do not combine mutations)
- For each mutant, recompile the mutated source into a callable function. Then run it against a provided array of test cases: `{ input: unknown[], expectedOutput: unknown }`
- A mutant survives if the mutated function produces the expected output for **all** provided test cases. That means the tests failed to detect the mutation. A mutant is killed if at least one test case fails against it
- Report a mutation score: `killed / totalMutants`

**Function signature:**

```typescript
interface Mutant {
  mutatedSource: string;
  description: string; // e.g. "line 3: '>' mutated to '>='"
}

interface TestCase {
  input: unknown[];
  expectedOutput: unknown;
}

function generateMutants(source: string): Mutant[];

function runMutationTesting(
  source: string,
  testCases: TestCase[]
): { mutationScore: number; survivedMutants: Mutant[] };
```

**Example:**

- Source: `function isEligible(age) { return age >= 18; }`
- Test cases: `[{ input: [20], expectedOutput: true }, { input: [10], expectedOutput: false }]`
- Mutate `>=` to `>`. Then `age > 18` still gives `true` for 20 and `false` for 10, so the mutant **survives**. The suite is weak: it never tests the boundary `age === 18`
- Adding a test case `{ input: [18], expectedOutput: true }` would kill that mutant

**Edge cases:**

- Source with no mutable operators → return empty mutants array, mutation score should be treated as not applicable (or 1.0 by convention — document your choice)
- Mutated source that throws a runtime error when executed against a test case → treat as killed. An error is a detectable difference from the expected output, not a silent survival
- Multiple occurrences of the same operator in one function → each occurrence produces a separate mutant (mutating only one occurrence at a time)

description.ru:
У вашей команды 100% покрытия по строкам (line coverage) на модуле `discountCalculator`, но в прод всё равно ушёл баг: неверный оператор сравнения. Существующие тесты ни разу не проверяли ту границу, которая бы его поймала.

Постройте минимальный движок мутационного тестирования. Он берёт исходный код функции как строку и применяет небольшие семантические мутации: например, переворачивает `>` в `>=` или `&&` в `||`.

Дальше он перезапускает переданный набор тестов против каждого мутанта и сообщает, какие мутации выжили. Выжила мутация — значит, тесты прошли, хотя код стал неверным. Каждый выживший мутант указывает на пробел, которого не видит покрытие по строкам и ветвям.

**Требования:**

- Реализуйте мутаторы минимум для трёх групп. Развороты сравнений: `>` ↔ `>=`, `<` ↔ `<=`, `===` ↔ `!==`. Развороты булевой логики: `&&` ↔ `||`. Развороты арифметики: `+` ↔ `-`
- Для заданной строки исходника сгенерируйте все варианты с одной мутацией (одна мутация на вариант, комбинировать мутации нельзя)
- Для каждого мутанта перекомпилируйте мутированный исходник в вызываемую функцию. Затем прогоните её против переданного массива тест-кейсов: `{ input: unknown[], expectedOutput: unknown }`
- Мутант выживает, если мутированная функция даёт ожидаемый результат для **всех** переданных тест-кейсов. Это значит, что тесты не смогли обнаружить мутацию. Мутант убит, если хотя бы один тест-кейс на нём не проходит
- Верните долю убитых мутантов (mutation score): `killed / totalMutants`

**Сигнатура функции:**

```typescript
interface Mutant {
  mutatedSource: string;
  description: string; // например "line 3: '>' mutated to '>='"
}

interface TestCase {
  input: unknown[];
  expectedOutput: unknown;
}

function generateMutants(source: string): Mutant[];

function runMutationTesting(
  source: string,
  testCases: TestCase[]
): { mutationScore: number; survivedMutants: Mutant[] };
```

**Пример:**

- Исходник: `function isEligible(age) { return age >= 18; }`
- Тест-кейсы: `[{ input: [20], expectedOutput: true }, { input: [10], expectedOutput: false }]`
- Мутируем `>=` в `>`. Тогда `age > 18` всё ещё даёт `true` для 20 и `false` для 10, и мутант **выживает**. Набор тестов слабый: он не проверяет границу `age === 18`
- Добавление тест-кейса `{ input: [18], expectedOutput: true }` убило бы этого мутанта

**Граничные случаи:**

- Исходник без мутируемых операторов → верните пустой массив мутантов, а долю убитых считайте неприменимой (или равной 1.0 по договорённости — задокументируйте свой выбор)
- Мутированный исходник, который падает с ошибкой во время выполнения на тест-кейсе → считайте убитым. Ошибка — это обнаружимое отличие от ожидаемого результата, а не тихое выживание
- Несколько вхождений одного оператора в одной функции → каждое вхождение даёт отдельного мутанта (мутируется только одно вхождение за раз)

