solution:
interface Mutant {
  mutatedSource: string;
  description: string;
}

interface TestCase {
  input: unknown[];
  expectedOutput: unknown;
}

// Ordered longest-first so we don't accidentally match '>' inside '>=' etc.
const OPERATOR_MUTATIONS: [string, string][] = [
  ['>=', '>'],
  ['<=', '<'],
  ['===', '!=='],
  ['!==', '==='],
  ['&&', '||'],
  ['||', '&&'],
  ['>', '>='],
  ['<', '<='],
  ['+', '-'],
  ['-', '+'],
];

function findOperatorOccurrences(source: string, operator: string): number[] {
  const positions: number[] = [];
  let idx = source.indexOf(operator);
  while (idx !== -1) {
    positions.push(idx);
    idx = source.indexOf(operator, idx + operator.length);
  }
  return positions;
}

function isPositionAlreadyConsumed(pos: number, len: number, consumed: [number, number][]): boolean {
  return consumed.some(([start, end]) => pos < end && pos + len > start);
}

function generateMutants(source: string): Mutant[] {
  const mutants: Mutant[] = [];
  const consumedRanges: [number, number][] = []; // tracks operator spans already matched by a longer operator

  for (const [from, to] of OPERATOR_MUTATIONS) {
    const positions = findOperatorOccurrences(source, from);
    for (const pos of positions) {
      if (isPositionAlreadyConsumed(pos, from.length, consumedRanges)) continue;

      // Skip '+'/'-' mutations that are inside longer operators already handled (defensive)
      const mutatedSource = source.slice(0, pos) + to + source.slice(pos + from.length);
      mutants.push({
        mutatedSource,
        description: `position ${pos}: '${from}' mutated to '${to}'`,
      });
    }
    // mark these positions consumed so shorter/overlapping operators don't double-mutate the same spot
    for (const pos of positions) {
      consumedRanges.push([pos, pos + from.length]);
    }
  }

  return mutants;
}

function evaluateFunctionSource(source: string): (...args: unknown[]) => unknown {
  // Wrap and return the declared function via an IIFE
  const factory = new Function(`${source}\nreturn arguments[0];`);
  const match = source.match(/function\s+(\w+)/);
  const fnName = match ? match[1] : null;
  if (!fnName) throw new Error('could not locate function name in source');

  const wrapped = new Function(`${source}\nreturn ${fnName};`);
  return wrapped() as (...args: unknown[]) => unknown;
}

function runMutationTesting(
  source: string,
  testCases: TestCase[]
): { mutationScore: number; survivedMutants: Mutant[] } {
  const mutants = generateMutants(source);

  if (mutants.length === 0) {
    return { mutationScore: 1, survivedMutants: [] };
  }

  const survivedMutants: Mutant[] = [];

  for (const mutant of mutants) {
    let survived = true;
    try {
      const mutatedFn = evaluateFunctionSource(mutant.mutatedSource);
      for (const testCase of testCases) {
        let actual: unknown;
        try {
          actual = mutatedFn(...testCase.input);
        } catch {
          survived = false; // runtime error counts as killed
          break;
        }
        if (actual !== testCase.expectedOutput) {
          survived = false;
          break;
        }
      }
    } catch {
      survived = false; // failed to even compile/evaluate: treat as killed
    }

    if (survived) {
      survivedMutants.push(mutant);
    }
  }

  const killed = mutants.length - survivedMutants.length;
  const mutationScore = killed / mutants.length;

  return { mutationScore, survivedMutants };
}

describe('mutation testing engine', () => {
  test('detects a survived mutant for a weak test suite', () => {
    const source = 'function isEligible(age) { return age >= 18; }';
    const testCases: TestCase[] = [
      { input: [20], expectedOutput: true },
      { input: [10], expectedOutput: false },
    ];

    const result = runMutationTesting(source, testCases);
    expect(result.survivedMutants.some((m) => m.description.includes("'>=' mutated to '>'"))).toBe(
      true
    );
  });

  test('a strengthened test suite kills the boundary mutant', () => {
    const source = 'function isEligible(age) { return age >= 18; }';
    const testCases: TestCase[] = [
      { input: [20], expectedOutput: true },
      { input: [10], expectedOutput: false },
      { input: [18], expectedOutput: true }, // boundary case added
    ];

    const result = runMutationTesting(source, testCases);
    expect(result.survivedMutants.some((m) => m.description.includes("'>=' mutated to '>'"))).toBe(
      false
    );
    expect(result.mutationScore).toBe(1);
  });

  test('source with no mutable operators returns empty mutants and score 1', () => {
    const source = 'function identity(x) { return x; }';
    const result = runMutationTesting(source, [{ input: [5], expectedOutput: 5 }]);
    expect(result.survivedMutants).toEqual([]);
    expect(result.mutationScore).toBe(1);
  });
});

description.en:
Your team wants visual regression testing for a component library. Screenshots of rendered components are compared against committed baseline images.

Naive pixel-for-pixel comparison is too strict. Anti-aliasing differences between continuous integration (CI) runs and tiny font-rendering variance cause false positives on every run.

Build a diffing utility that compares two same-sized images and decides pass or fail with a tunable tolerance. The images arrive as flat RGBA byte arrays, one byte each for red, green, blue and alpha. The utility also produces a visual diff overlay.

**Requirements:**

- Implement pixel-by-pixel comparison between a baseline and a candidate image (same width/height, RGBA `Uint8ClampedArray`-like number arrays)
- Support two thresholds at once. A per-pixel color-distance threshold: small differences within the threshold do not count as a mismatch, which absorbs anti-aliasing noise. An overall mismatch-percentage threshold: fail only if more than 0.1% of pixels differ beyond the per-pixel threshold
- Generate a diff image that highlights mismatched pixels, for example painting them solid red. Keep matched regions faithful to the baseline, or dim them — your choice, document it. A human reviewer must be able to see **where** the regression is
- Images of different dimensions should fail fast with a clear reason, not attempt a pixel comparison

**Function signature:**

```typescript
interface ImageData2 {
  width: number;
  height: number;
  data: number[]; // flat RGBA, length = width * height * 4
}

interface DiffOptions {
  pixelColorThreshold?: number; // default 32 (0-255 scale, euclidean-ish distance)
  maxMismatchPercentage?: number; // default 0.1 (percent, i.e. 0.1 = 0.1%)
}

interface DiffResult {
  passed: boolean;
  mismatchedPixelCount: number;
  mismatchPercentage: number;
  diffImage: ImageData2;
  reason?: string;
}

function compareImages(
  baseline: ImageData2,
  candidate: ImageData2,
  options?: DiffOptions
): DiffResult;
```

**Example:**

- Identical images → `passed: true`, `mismatchedPixelCount: 0`
- One pixel out of 10,000 is the fully opposite color, black against white, at the default 0.1% threshold. Then 1/10000 = 0.01%, which is below 0.1%, so `passed: true`. The field `mismatchedPixelCount` still reports `1`
- Same scenario but with `maxMismatchPercentage: 0.005` → `passed: false`

**Edge cases:**

- Different width/height between baseline and candidate → `passed: false` and `reason: 'dimension mismatch'`, with no pixel comparison attempted. Still return a valid `diffImage` shape: same as the candidate, or empty, your documented choice
- All pixels within color threshold but exactly at the boundary value → **not** a mismatch, since the threshold treats the boundary as close enough
- Fully transparent pixels (alpha = 0) with different colors underneath → decide and document whether alpha is factored into the distance calculation

description.ru:
Команда хочет визуальное регрессионное тестирование для библиотеки компонентов: скриншоты отрендеренных компонентов сравниваются с закоммиченными эталонными изображениями.

Наивное попиксельное сравнение слишком строгое. Различия сглаживания (anti-aliasing) между прогонами непрерывной интеграции (CI) и крошечные вариации рендеринга шрифтов дают ложные срабатывания на каждом прогоне.

Постройте утилиту сравнения, которая берёт два изображения одинакового размера и решает «прошло» или «упало» с настраиваемым допуском. Изображения приходят как плоские массивы байтов RGBA (red, green, blue, alpha — красный, зелёный, синий и прозрачность). Ещё утилита рисует наглядный оверлей различий.

**Требования:**

- Реализуйте попиксельное сравнение эталона и кандидата (одинаковые ширина и высота, массивы чисел RGBA вроде `Uint8ClampedArray`)
- Поддержите сразу два порога. Порог цветовой дистанции на пиксель: небольшие различия в пределах порога не считаются несовпадением, и это поглощает шум сглаживания. Порог общего процента несовпадений: падать только если сверх первого порога отличается больше 0.1% пикселей
- Сгенерируйте diff-изображение, которое подсвечивает несовпадающие пиксели, например сплошным красным. Совпадающие области оставьте верными эталону или затемните — выбор ваш, задокументируйте его. Человек-ревьюер должен видеть, **где** регрессия
- Изображения разных размеров должны падать сразу с понятной причиной, без попиксельного сравнения

**Сигнатура функции:**

```typescript
interface ImageData2 {
  width: number;
  height: number;
  data: number[]; // плоский RGBA, длина = width * height * 4
}

interface DiffOptions {
  // по умолчанию 32 (шкала 0-255, евклидова дистанция по цвету)
  pixelColorThreshold?: number;
  maxMismatchPercentage?: number; // по умолчанию 0.1 (т.е. 0.1 = 0.1%)
}

interface DiffResult {
  passed: boolean;
  mismatchedPixelCount: number;
  mismatchPercentage: number;
  diffImage: ImageData2;
  reason?: string;
}

function compareImages(
  baseline: ImageData2,
  candidate: ImageData2,
  options?: DiffOptions
): DiffResult;
```

**Пример:**

- Идентичные изображения → `passed: true`, `mismatchedPixelCount: 0`
- Один пиксель из 10000 полностью противоположного цвета, чёрный против белого, при дефолтном пороге 0.1%. Тогда 1/10000 = 0.01%, это ниже 0.1%, поэтому `passed: true`. Поле `mismatchedPixelCount` всё равно показывает `1`
- Тот же сценарий, но с `maxMismatchPercentage: 0.005` → `passed: false`

**Граничные случаи:**

- Разная ширина или высота у эталона и кандидата → `passed: false` и `reason: 'dimension mismatch'`, попиксельное сравнение не выполняется. Всё равно верните валидную форму `diffImage`: такую же, как у кандидата, или пустую — задокументируйте выбор
- Все пиксели в пределах порога цвета, но ровно на граничном значении → это **не** несовпадение: граница считается достаточно близкой
- Полностью прозрачные пиксели (alpha = 0) с разными цветами под ними → решите и задокументируйте, учитывается ли прозрачность в расчёте дистанции

