solution:
interface ImageData2 {
  width: number;
  height: number;
  data: number[];
}

interface DiffOptions {
  pixelColorThreshold?: number;
  maxMismatchPercentage?: number;
}

interface DiffResult {
  passed: boolean;
  mismatchedPixelCount: number;
  mismatchPercentage: number;
  diffImage: ImageData2;
  reason?: string;
}

function pixelColorDistance(
  r1: number, g1: number, b1: number,
  r2: number, g2: number, b2: number
): number {
  const dr = r1 - r2;
  const dg = g1 - g2;
  const db = b1 - b2;
  return Math.sqrt(dr * dr + dg * dg + db * db);
}

const DIFF_HIGHLIGHT_COLOR = [255, 0, 0, 255] as const; // solid red, fully opaque

function compareImages(
  baseline: ImageData2,
  candidate: ImageData2,
  options: DiffOptions = {}
): DiffResult {
  const pixelColorThreshold = options.pixelColorThreshold ?? 32;
  const maxMismatchPercentage = options.maxMismatchPercentage ?? 0.1;

  if (baseline.width !== candidate.width || baseline.height !== candidate.height) {
    return {
      passed: false,
      mismatchedPixelCount: 0,
      mismatchPercentage: 0,
      diffImage: { width: candidate.width, height: candidate.height, data: [...candidate.data] },
      reason: 'dimension mismatch',
    };
  }

  const { width, height } = baseline;
  const totalPixels = width * height;
  const diffData = new Array<number>(baseline.data.length);
  let mismatchedPixelCount = 0;

  for (let i = 0; i < totalPixels; i++) {
    const offset = i * 4;
    const [r1, g1, b1] = [
      baseline.data[offset],
      baseline.data[offset + 1],
      baseline.data[offset + 2],
    ];
    const [r2, g2, b2] = [
      candidate.data[offset],
      candidate.data[offset + 1],
      candidate.data[offset + 2],
    ];
    // Alpha is intentionally excluded from the distance calculation: fully transparent
    // pixels with differing underlying RGB are not visually distinguishable, so comparing
    // RGB only avoids false positives on transparent regions.

    const distance = pixelColorDistance(r1, g1, b1, r2, g2, b2);
    const isMismatch = distance > pixelColorThreshold; // strictly greater: boundary value counts as "close enough"

    if (isMismatch) {
      mismatchedPixelCount += 1;
      diffData[offset] = DIFF_HIGHLIGHT_COLOR[0];
      diffData[offset + 1] = DIFF_HIGHLIGHT_COLOR[1];
      diffData[offset + 2] = DIFF_HIGHLIGHT_COLOR[2];
      diffData[offset + 3] = DIFF_HIGHLIGHT_COLOR[3];
    } else {
      // keep matched regions faithful to the baseline for reviewer context
      diffData[offset] = baseline.data[offset];
      diffData[offset + 1] = baseline.data[offset + 1];
      diffData[offset + 2] = baseline.data[offset + 2];
      diffData[offset + 3] = baseline.data[offset + 3];
    }
  }

  const mismatchPercentage = (mismatchedPixelCount / totalPixels) * 100;
  const passed = mismatchPercentage <= maxMismatchPercentage;

  return {
    passed,
    mismatchedPixelCount,
    mismatchPercentage,
    diffImage: { width, height, data: diffData },
  };
}

function makeSolidImage(width: number, height: number, r: number, g: number, b: number, a = 255): ImageData2 {
  const data = new Array<number>(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    data[i * 4] = r;
    data[i * 4 + 1] = g;
    data[i * 4 + 2] = b;
    data[i * 4 + 3] = a;
  }
  return { width, height, data };
}

describe('compareImages', () => {
  test('identical images pass with zero mismatches', () => {
    const image = makeSolidImage(100, 100, 200, 200, 200);
    const result = compareImages(image, { ...image, data: [...image.data] });
    expect(result.passed).toBe(true);
    expect(result.mismatchedPixelCount).toBe(0);
  });

  test('single fully-opposite pixel below percentage threshold still passes', () => {
    const baseline = makeSolidImage(100, 100, 0, 0, 0); // 10000 pixels, black
    const candidate = makeSolidImage(100, 100, 0, 0, 0);
    candidate.data[0] = 255;
    candidate.data[1] = 255;
    candidate.data[2] = 255; // one pixel now white

    const result = compareImages(baseline, candidate); // default 0.1% threshold
    expect(result.mismatchedPixelCount).toBe(1);
    expect(result.passed).toBe(true); // 0.01% < 0.1%
  });

  test('stricter percentage threshold fails on the same single-pixel diff', () => {
    const baseline = makeSolidImage(100, 100, 0, 0, 0);
    const candidate = makeSolidImage(100, 100, 0, 0, 0);
    candidate.data[0] = 255;
    candidate.data[1] = 255;
    candidate.data[2] = 255;

    const result = compareImages(baseline, candidate, { maxMismatchPercentage: 0.005 });
    expect(result.passed).toBe(false);
  });

  test('dimension mismatch fails fast with a reason, no pixel comparison', () => {
    const baseline = makeSolidImage(100, 100, 0, 0, 0);
    const candidate = makeSolidImage(50, 50, 0, 0, 0);

    const result = compareImages(baseline, candidate);
    expect(result.passed).toBe(false);
    expect(result.reason).toBe('dimension mismatch');
  });

  test('small color difference within threshold is not a mismatch (anti-aliasing tolerance)', () => {
    const baseline = makeSolidImage(10, 10, 100, 100, 100);
    const candidate = makeSolidImage(10, 10, 110, 110, 110); // small AA-like drift

    const result = compareImages(baseline, candidate); // default pixelColorThreshold 32
    expect(result.mismatchedPixelCount).toBe(0);
  });
});

description.en:
You have a host application that loads a `ProductCard` micro-frontend (MFE) remotely, through Webpack Module Federation. Each MFE is built, versioned and deployed on its own.

That independence is the problem. A unit test inside the remote's own repository, with the real component, can pass while the host still breaks in production. It happens when the remote starts requiring a prop the host does not pass. It also happens when host and remote disagree on which shared dependency version to use at runtime.

Build a test harness that catches integration issues **without** spinning up both real applications together in a browser.

**Requirements:**

- Write a `validateRemoteContract` function. It takes two inputs: the prop shape the remote's component expects, and the exact props the host passes at its call site. The prop shape is a lightweight prop-types-like descriptor, name → 'required' | 'optional'. The function reports missing required props, and extra props the host thinks the remote wants
- Write a `checkSharedDependencyCompatibility` function. It takes the host's declared shared-dependency versions, for example `{ react: '18.2.0', 'react-dom': '18.2.0' }`. It also takes the remote's declared requirements, each a semver range, for example `{ react: '^18.0.0' }`. It reports every dependency whose host version does **not** satisfy the remote's range. This is the exact class of bug where host and remote silently load two different React instances at runtime, which produces invisible hook errors
- Write a `simulateRemoteLoadFailure` test that shows the host's fallback behavior when the remote module fails to load. Causes include a network failure or an unavailable remote build. The host must render a fallback screen through its error boundary, not crash the whole app
- All three functions must be usable in a continuous integration (CI) step that runs **before** deployment. The remote's real bundle never has to be fetched over the network

**Function signature:**

```typescript
type PropRequirement = 'required' | 'optional';

function validateRemoteContract(
  expectedProps: Record<string, PropRequirement>,
  actualProps: Record<string, unknown>
): { valid: boolean; missingRequired: string[]; unknownExtra: string[] };

function checkSharedDependencyCompatibility(
  hostVersions: Record<string, string>,
  remoteRequiredRanges: Record<string, string>
): {
  compatible: boolean;
  incompatibleDeps: {
    dep: string;
    hostVersion: string;
    requiredRange: string;
  }[];
};
```

**Example:**

- `expectedProps = { productId: 'required', onAddToCart: 'required', theme: 'optional' }`, `actualProps = { productId: '1' }` → missing `onAddToCart`
- `hostVersions = { react: '17.0.2' }`, `remoteRequiredRanges = { react: '^18.0.0' }` → incompatible, since 17.0.2 doesn't satisfy `^18.0.0`

**Edge cases:**

- Host passes an extra prop the remote's contract doesn't list at all → flagged as `unknownExtra` (likely a stale integration or typo)
- Remote contract has zero required props → any `actualProps` (even empty) is valid
- Semver range check should handle prerelease-free ranges correctly. The range `^18.0.0` is satisfied by `18.5.3`, and not by `17.9.9` or `19.0.0`

description.ru:
У вас есть хост-приложение, которое удалённо загружает микрофронтенд (MFE) `ProductCard` через Webpack Module Federation. Каждый MFE собирается, версионируется и деплоится сам по себе.

Эта независимость и есть проблема. Юнит-тест внутри репозитория самого удалённого модуля, с реальным компонентом, может проходить, а хост при этом ломается в проде. Так бывает, когда удалённый модуль начинает требовать проп, который хост не передаёт. И так бывает, когда хост и модуль расходятся в том, какую версию общей зависимости брать в рантайме.

Постройте тестовый харнесс, который ловит проблемы интеграции **без** запуска обоих реальных приложений вместе в браузере.

**Требования:**

- Напишите функцию `validateRemoteContract`. На вход она берёт две вещи: ожидаемую форму пропов компонента, который отдаёт удалённый модуль, и точный объект пропов, который хост передаёт в точке вызова. Форма пропов — лёгкий дескриптор в духе prop-types: имя → 'required' | 'optional'. Функция сообщает об отсутствующих обязательных пропах и о лишних пропах, которые хост считает нужными модулю
- Напишите функцию `checkSharedDependencyCompatibility`. Она берёт заявленные хостом версии общих зависимостей, например `{ react: '18.2.0', 'react-dom': '18.2.0' }`. Ещё она берёт требования удалённого модуля, каждое как semver-диапазон, например `{ react: '^18.0.0' }`. Она сообщает о каждой зависимости, чья версия у хоста **не** попадает в диапазон модуля. Это ровно тот класс багов, когда хост и модуль незаметно грузят два разных инстанса React и получают невидимые ошибки хуков
- Напишите тест `simulateRemoteLoadFailure`, показывающий поведение хоста, когда модуль не загружается: сетевой сбой или недоступная сборка. Хост должен отрисовать запасной экран через error boundary, а не уронить всё приложение
- Все три функции должны работать в шаге непрерывной интеграции (CI), который выполняется **до** деплоя. Реальный бандл модуля при этом по сети не грузится

**Сигнатура функции:**

```typescript
type PropRequirement = 'required' | 'optional';

function validateRemoteContract(
  expectedProps: Record<string, PropRequirement>,
  actualProps: Record<string, unknown>
): { valid: boolean; missingRequired: string[]; unknownExtra: string[] };

function checkSharedDependencyCompatibility(
  hostVersions: Record<string, string>,
  remoteRequiredRanges: Record<string, string>
): {
  compatible: boolean;
  incompatibleDeps: {
    dep: string;
    hostVersion: string;
    requiredRange: string;
  }[];
};
```

**Пример:**

- `expectedProps = { productId: 'required', onAddToCart: 'required', theme: 'optional' }`, `actualProps = { productId: '1' }` → отсутствует `onAddToCart`
- `hostVersions = { react: '17.0.2' }`, `remoteRequiredRanges = { react: '^18.0.0' }` → несовместимо, так как 17.0.2 не удовлетворяет `^18.0.0`

**Граничные случаи:**

- Хост передаёт лишний проп, которого вообще нет в контракте модуля → помечается как `unknownExtra` (вероятно, устаревшая интеграция или опечатка)
- В контракте модуля ноль обязательных пропов → любые `actualProps` (даже пустые) валидны
- Проверка semver-диапазона должна корректно обрабатывать диапазоны без prerelease. Диапазону `^18.0.0` удовлетворяет `18.5.3`, но не `17.9.9` и не `19.0.0`

