solution:
interface DbConnection {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
  begin(): Promise<void>;
  rollback(): Promise<void>;
  commit(): Promise<void>;
}

interface UserRow {
  id: string;
  email: string;
  role: string | null;
  active: boolean;
}

// In-memory fake standing in for a real Testcontainers-provisioned Postgres instance.
// Implements real SQL NULL semantics for the subset of behavior this exercise needs,
// so the same bug that a real engine would expose is reproducible here.
class FakeSqlEngine implements DbConnection {
  private committedRows: UserRow[] = [];
  private transactionRows: UserRow[] | null = null;
  private nextId = 1;

  private get activeRows(): UserRow[] {
    return this.transactionRows ?? this.committedRows;
  }

  async begin(): Promise<void> {
    // snapshot committed state into a working copy; mutations during the
    // transaction only affect this copy until commit
    this.transactionRows = [...this.committedRows];
  }

  async rollback(): Promise<void> {
    this.transactionRows = null; // discard the working copy entirely
  }

  async commit(): Promise<void> {
    if (this.transactionRows) {
      this.committedRows = this.transactionRows;
      this.transactionRows = null;
    }
  }

  async query<T>(sql: string, params: unknown[]): Promise<T[]> {
    if (sql.startsWith('INSERT')) {
      const [email, role, active] = params as [string, string | null, boolean];
      const row: UserRow = { id: String(this.nextId++), email, role, active };
      this.activeRows.push(row);
      return [row] as unknown as T[];
    }

    if (sql.includes('IS NULL')) {
      const [active] = params as [boolean];
      return this.activeRows.filter((r) => r.role === null && r.active === active) as unknown as T[];
    }

    if (sql.includes('role = $1')) {
      const [role, active] = params as [string, boolean];
      // Faithfully reproduces real SQL: '=' comparison against NULL never matches,
      // even if role happens to equal null at the JS level, mirroring Postgres semantics.
      return this.activeRows.filter((r) => r.role !== null && r.role === role && r.active === active) as unknown as T[];
    }

    return [] as unknown as T[];
  }
}

class DatabaseTestHarness {
  private engine: FakeSqlEngine;

  private constructor(engine: FakeSqlEngine) {
    this.engine = engine;
  }

  static async start(): Promise<DatabaseTestHarness> {
    // Simulates the async container-provisioning step (image pull, port binding,
    // readiness poll) that a real Testcontainers setup would perform here.
    await new Promise((resolve) => setTimeout(resolve, 0));
    return new DatabaseTestHarness(new FakeSqlEngine());
  }

  getConnection(): DbConnection {
    return this.engine;
  }

  async stop(): Promise<void> {
    // Simulates container teardown.
  }
}

class UserRepository {
  constructor(private db: DbConnection) {}

  async findActiveUsersByRole(role: string | null): Promise<UserRow[]> {
    if (role === null) {
      // Correct NULL handling: 'IS NULL', not '= NULL'
      return this.db.query<UserRow>('SELECT * FROM users WHERE role IS NULL AND active = $1', [true]);
    }
    return this.db.query<UserRow>('SELECT * FROM users WHERE role = $1 AND active = $2', [role, true]);
  }
}

describe('UserRepository integration (real DB semantics)', () => {
  let harness: DatabaseTestHarness;
  let db: DbConnection;
  let repo: UserRepository;

  beforeAll(async () => {
    harness = await DatabaseTestHarness.start();
    db = harness.getConnection();
    repo = new UserRepository(db);
  });

  afterAll(async () => {
    await harness.stop();
  });

  beforeEach(async () => {
    await db.begin();
  });

  afterEach(async () => {
    // Rollback per test is dramatically cheaper than re-seeding the whole DB:
    // it's an O(1) discard of the transaction's working copy rather than
    // O(n) delete-and-reinsert of every seed row for every single test.
    await db.rollback();
  });

  test('returns only active users matching a non-null role', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['a@x.com', 'admin', true]);
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['b@x.com', 'admin', false]);

    const results = await repo.findActiveUsersByRole('admin');
    expect(results).toHaveLength(1);
    expect(results[0].email).toBe('a@x.com');
  });

  test('correctly handles NULL role lookup (catches the production bug)', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['b@x.com', null, true]);

    const results = await repo.findActiveUsersByRole(null);
    expect(results).toHaveLength(1);
    expect(results[0].email).toBe('b@x.com');
  });

  test('role with zero matching users returns empty array, not an error', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['a@x.com', 'admin', true]);

    const results = await repo.findActiveUsersByRole('nonexistent-role');
    expect(results).toEqual([]);
  });

  test('duplicate email across two sequential tests does not conflict (isolation proof, test 1)', async () => {
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['dup@x.com', 'member', true]);
    const results = await repo.findActiveUsersByRole('member');
    expect(results).toHaveLength(1);
  });

  test('duplicate email across two sequential tests does not conflict (isolation proof, test 2)', async () => {
    // If the rollback in the previous test's afterEach hadn't worked, this insert
    // would collide with or duplicate the previous test's row.
    await db.query('INSERT INTO users (email, role, active) VALUES ($1, $2, $3)', ['dup@x.com', 'member', true]);
    const results = await repo.findActiveUsersByRole('member');
    expect(results).toHaveLength(1); // still just this test's own row, not 2
  });
});

description.en:
Your continuous integration (CI) suite has 500 test files and takes 25 minutes on a single runner. You want to split it across N parallel CI workers to cut wall-clock time.

A naive round-robin split by file order gives wildly uneven shard durations: some shards finish in 2 minutes, others take 15. Test files vary enormously in runtime.

You also want automatic retry for known-flaky tests. It must **not** mask genuinely broken tests as merely flaky.

**Requirements:**

- Write an `assignTestsToShards` function. It takes a list of test files with their historical durations, from a previous CI run, plus a shard count N. It distributes files across shards so that the gap between the longest and the shortest shard duration is as small as possible. This is a bin-packing, or partition, problem. An exact optimum is not required, but your heuristic must be clearly better than round-robin on skewed input
- Write a `shouldRetryTest` function with a bounded, tracked retry policy. A test tagged known-flaky gets up to 2 automatic retries on failure. The retry must be reported separately from a first-attempt pass, so a test that only passes on retry stays **visible** in CI reports. The goal is retry with transparency, not retry that hides problems
- A test **not** tagged as known-flaky must never be auto-retried, even when it fails. Auto-retrying arbitrary failures is exactly the anti-pattern that hides real regressions
- Track and expose a per-test flake rate over the last M runs. Flag any test whose flake rate crosses a threshold: failing first and passing on retry in more than 20% of the last 20 runs. Such a test is a candidate for the team to fix or quarantine, not to leave auto-retried forever

**Function signature:**

```typescript
interface TestFileInfo {
  path: string;
  historicalDurationMs: number;
}

function assignTestsToShards(files: TestFileInfo[], shardCount: number): TestFileInfo[][];

interface RetryDecision {
  shouldRetry: boolean;
  reason: string;
}

function shouldRetryTest(
  testName: string,
  isKnownFlaky: boolean,
  attemptNumber: number, // 1 = first attempt
  maxRetries: number
): RetryDecision;

function computeFlakeRate(
  recentOutcomes: ('passed-first-try' | 'passed-on-retry' | 'failed')[]
): number;
```

**Example:**

- 4 files with durations `[10, 10, 10, 1]` minutes split into 2 shards. A good split is `[10, 1]` and `[10, 10]`, that is 11 against 20. It stays uneven because three tens do not divide evenly into two shards
- A less trivial example shows the gain: `[8, 5, 5, 4, 3]` into 2 shards. Greedy longest-first assignment gives `[8, 4]` = 12 and `[5, 5, 3]` = 13, much closer than a naive split by file order
- `shouldRetryTest('checkout flow', true, 2, 2)` → `{ shouldRetry: true, reason: 'known-flaky, attempt 2 of 3 allowed' }`
- `shouldRetryTest('checkout flow', false, 2, 2)` → `{ shouldRetry: false, reason: 'not marked as known-flaky, failures are not auto-retried' }`

**Edge cases:**

- `shardCount` greater than number of files → some shards end up empty, function must not throw
- All files have identical duration → any assignment is equally optimal, round-robin is fine here
- `attemptNumber` exceeds `maxRetries + 1` even for a known-flaky test → `shouldRetry: false`. The reason must say retries are exhausted, and must not be confused with not being flaky

description.ru:
У вашего набора тестов в CI (continuous integration — непрерывная интеграция) 500 файлов, и на одном раннере он идёт 25 минут. Вы хотите разложить его на N параллельных воркеров CI, чтобы сократить время по часам.

Наивное разбиение round-robin по порядку файлов даёт дико неравномерные шарды: одни заканчиваются за 2 минуты, другие идут 15. Файлы тестов сильно различаются по времени выполнения.

Ещё нужен автоматический повтор для известно флейковых тестов. Он **не** должен выдавать по-настоящему сломанный тест за просто флейковый.

**Требования:**

- Напишите функцию `assignTestsToShards`. Она берёт список тестовых файлов с их историческими длительностями из предыдущего прогона CI и число шардов N. Она раскладывает файлы по шардам так, чтобы разрыв между самым длинным и самым коротким шардом был как можно меньше. Это задача упаковки в контейнеры, она же задача разбиения. Точный оптимум не требуется, но ваша эвристика должна быть явно лучше round-robin на перекошенном входе
- Напишите функцию `shouldRetryTest` с ограниченной и отслеживаемой политикой повторов. Тест, помеченный как известно флейковый, получает до 2 автоматических повторов при падении. Повтор обязан попадать в отчёт отдельно от прохождения с первой попытки, чтобы тест, который проходит только на повторе, оставался **видимым** в отчётах CI. Цель — повтор с прозрачностью, а не повтор ради сокрытия проблем
- Тест, **не** помеченный как известно флейковый, повторять автоматически нельзя никогда, даже если он упал. Автоповтор произвольных падений — ровно тот антипаттерн, который скрывает реальные регрессии
- Считайте и выставляйте наружу долю флейков по каждому тесту за последние M прогонов. Помечайте тест, у которого эта доля перешла порог: упал сначала и прошёл на повторе больше чем в 20% последних 20 прогонов. Такой тест — кандидат на то, чтобы команда его починила или закарантинила, а не оставила вечно на автоповторах

**Сигнатура функции:**

```typescript
interface TestFileInfo {
  path: string;
  historicalDurationMs: number;
}

function assignTestsToShards(files: TestFileInfo[], shardCount: number): TestFileInfo[][];

interface RetryDecision {
  shouldRetry: boolean;
  reason: string;
}

function shouldRetryTest(
  testName: string,
  isKnownFlaky: boolean,
  attemptNumber: number, // 1 = первая попытка
  maxRetries: number
): RetryDecision;

function computeFlakeRate(
  recentOutcomes: ('passed-first-try' | 'passed-on-retry' | 'failed')[]
): number;
```

**Пример:**

- 4 файла с длительностями `[10, 10, 10, 1]` минут на 2 шарда. Хорошее разбиение — `[10, 1]` и `[10, 10]`, то есть 11 против 20. Ровным оно не станет: три десятки на два шарда поровну не делятся
- Выигрыш виднее на менее тривиальном примере: `[8, 5, 5, 4, 3]` на 2 шарда. Жадное распределение «сначала самые длинные» даёт `[8, 4]` = 12 и `[5, 5, 3]` = 13, что гораздо ближе, чем наивное разбиение по порядку
- `shouldRetryTest('checkout flow', true, 2, 2)` → `{ shouldRetry: true, reason: 'known-flaky, attempt 2 of 3 allowed' }`
- `shouldRetryTest('checkout flow', false, 2, 2)` → `{ shouldRetry: false, reason: 'not marked as known-flaky, failures are not auto-retried' }`

**Граничные случаи:**

- `shardCount` больше числа файлов → некоторые шарды остаются пустыми, функция не должна падать
- Все файлы с одинаковой длительностью → любое распределение одинаково оптимально, round-robin тут подходит
- `attemptNumber` превышает `maxRetries + 1` даже для известно флейкового теста → `shouldRetry: false`. Причина должна говорить об исчерпании повторов, и путать это с «не флейковый» нельзя

