import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';

interface ErrorBoundaryProps {
  onError?: (error: Error, componentStack: string) => void;
  fallback: (reset: () => void) => React.ReactNode;
  children: React.ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class FeatureErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    this.props.onError?.(error, info.componentStack ?? '');
  }

  reset = () => {
    this.setState({ hasError: false });
  };

  render() {
    if (this.state.hasError) {
      return this.props.fallback(this.reset);
    }
    return this.props.children;
  }
}

class AppErrorBoundary extends FeatureErrorBoundary {}

function BrokenWidget({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) {
    throw new Error('widget crashed');
  }
  return <div>Widget OK</div>;
}

function featureFallback(reset: () => void) {
  return (
    <div role="alert">
      <span>This section is unavailable</span>
      <button onClick={reset}>Try again</button>
    </div>
  );
}

function appFallback(reset: () => void) {
  return (
    <div role="alert" data-testid="app-fallback">
      <span>Something went wrong. Please reload.</span>
      <button onClick={reset}>Try again</button>
    </div>
  );
}

describe('error boundary hierarchy', () => {
  // Suppress React's noisy console.error for expected thrown errors in these tests
  let consoleErrorSpy: jest.SpyInstance;
  beforeEach(() => {
    consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
  });
  afterEach(() => {
    consoleErrorSpy.mockRestore();
  });

  test('feature-level error is isolated, siblings stay mounted', () => {
    render(
      <AppErrorBoundary fallback={appFallback}>
        <FeatureErrorBoundary fallback={featureFallback}>
          <BrokenWidget shouldThrow={true} />
        </FeatureErrorBoundary>
        <div>Other widget content</div>
      </AppErrorBoundary>
    );

    expect(screen.getByText('This section is unavailable')).toBeInTheDocument();
    expect(screen.getByText('Other widget content')).toBeInTheDocument();
    expect(screen.queryByTestId('app-fallback')).not.toBeInTheDocument();
  });

  test('error outside any feature boundary is caught by the app boundary, replacing everything', () => {
    render(
      <AppErrorBoundary fallback={appFallback}>
        <BrokenWidget shouldThrow={true} />
        <div>Other widget content</div>
      </AppErrorBoundary>
    );

    expect(screen.getByTestId('app-fallback')).toBeInTheDocument();
    expect(screen.queryByText('Other widget content')).not.toBeInTheDocument();
  });

  test('onError callback fires with the error object at whichever level catches it', () => {
    const onFeatureError = jest.fn();
    const onAppError = jest.fn();

    render(
      <AppErrorBoundary fallback={appFallback} onError={onAppError}>
        <FeatureErrorBoundary fallback={featureFallback} onError={onFeatureError}>
          <BrokenWidget shouldThrow={true} />
        </FeatureErrorBoundary>
      </AppErrorBoundary>
    );

    expect(onFeatureError).toHaveBeenCalledTimes(1);
    expect(onFeatureError.mock.calls[0][0].message).toBe('widget crashed');
    expect(onAppError).not.toHaveBeenCalled(); // inner boundary caught it, outer never saw it
  });

  test('reset re-attempts rendering original children once the cause is fixed', () => {
    function Wrapper() {
      const [shouldThrow, setShouldThrow] = React.useState(true);
      return (
        <FeatureErrorBoundary
          fallback={(reset) => (
            <div role="alert">
              <span>This section is unavailable</span>
              <button
                onClick={() => {
                  setShouldThrow(false); // fix the underlying cause first
                  reset();
                }}
              >
                Try again
              </button>
            </div>
          )}
        >
          <BrokenWidget shouldThrow={shouldThrow} />
        </FeatureErrorBoundary>
      );
    }

    render(<Wrapper />);
    expect(screen.getByText('This section is unavailable')).toBeInTheDocument();

    fireEvent.click(screen.getByText('Try again'));

    expect(screen.getByText('Widget OK')).toBeInTheDocument();
    expect(screen.queryByText('This section is unavailable')).not.toBeInTheDocument();
  });

  test('event handler errors are NOT caught by the boundary (React limitation)', () => {
    function ClickToThrow() {
      return (
        <button
          onClick={() => {
            throw new Error('event handler error');
          }}
        >
          Click me
        </button>
      );
    }

    render(
      <FeatureErrorBoundary fallback={featureFallback}>
        <ClickToThrow />
      </FeatureErrorBoundary>
    );

    expect(() => fireEvent.click(screen.getByText('Click me'))).toThrow('event handler error');
    // The boundary's fallback never appears - event handler errors bypass boundaries entirely.
    expect(screen.queryByText('This section is unavailable')).not.toBeInTheDocument();
  });
});
